### Python

```python
from collections import deque


# 判断一个状态是否满足所有极大连通块大小均为奇数
def check(state, n, m):
    visited = [[False] * m for _ in range(n)]
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # 获取某个位置的颜色，0表示白子，1表示黑子
    def get_color(x, y):
        idx = x * m + y
        return (state >> idx) & 1

    for i in range(n):
        for j in range(m):
            if visited[i][j]:
                continue

            # 从当前点开始BFS，统计同色连通块大小
            color = get_color(i, j)
            q = deque()
            q.append((i, j))
            visited[i][j] = True
            size = 0

            while q:
                x, y = q.popleft()
                size += 1

                for dx, dy in dirs:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < n and 0 <= ny < m and not visited[nx][ny]:
                        if get_color(nx, ny) == color:
                            visited[nx][ny] = True
                            q.append((nx, ny))

            # 如果某个极大连通块大小为偶数，则不合法
            if size % 2 == 0:
                return False

    return True


# 统计所有合法布局数量
def solve(n, m):
    total = n * m
    ans = 0

    # 枚举每一种黑白布局
    for state in range(1 << total):
        if check(state, n, m):
            ans += 1

    return ans


if __name__ == "__main__":
    n, m = map(int, input().split())
    print(solve(n, m))
```

### Java

```java
import java.util.LinkedList;
import java.util.Queue;
import java.util.Scanner;

public class Main {

    // 判断一个状态是否满足所有极大连通块大小均为奇数
    public static boolean check(int state, int n, int m) {
        boolean[][] visited = new boolean[n][m];
        int[] dx = {-1, 1, 0, 0};
        int[] dy = {0, 0, -1, 1};

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (visited[i][j]) {
                    continue;
                }

                // 当前格子的颜色
                int color = (state >> (i * m + j)) & 1;

                // BFS统计同色连通块大小
                Queue<int[]> queue = new LinkedList<>();
                queue.offer(new int[]{i, j});
                visited[i][j] = true;
                int size = 0;

                while (!queue.isEmpty()) {
                    int[] cur = queue.poll();
                    int x = cur[0];
                    int y = cur[1];
                    size++;

                    for (int k = 0; k < 4; k++) {
                        int nx = x + dx[k];
                        int ny = y + dy[k];

                        if (nx >= 0 && nx < n && ny >= 0 && ny < m && !visited[nx][ny]) {
                            int nextColor = (state >> (nx * m + ny)) & 1;
                            if (nextColor == color) {
                                visited[nx][ny] = true;
                                queue.offer(new int[]{nx, ny});
                            }
                        }
                    }
                }

                // 如果存在偶数大小连通块，则不合法
                if (size % 2 == 0) {
                    return false;
                }
            }
        }

        return true;
    }

    // 统计所有合法布局数量
    public static int solve(int n, int m) {
        int total = n * m;
        int ans = 0;

        // 枚举所有状态
        for (int state = 0; state < (1 << total); state++) {
            if (check(state, n, m)) {
                ans++;
            }
        }

        return ans;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        System.out.println(solve(n, m));
    }
}
```

