using namespace std;


// 判断一个状态是否满足所有极大连通块大小均为奇数
bool check(int state, int n, int m) {
    vector<vector<bool>> visited(n, vector<bool>(m, false));
    int dx[4] = {-1, 1, 0, 0};
    int dy[4] = {0, 0, -1, 1};

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (visited[i][j]) {
                continue;
            }

            // 当前格子的颜色
            int color = (state >> (i * m + j)) & 1;

            // BFS统计同色连通块大小
            queue<pair<int, int>> q;
            q.push({i, j});
            visited[i][j] = true;
            int size = 0;

            while (!q.empty()) {
                pair<int, int> cur = q.front();
                q.pop();
                int x = cur.first;
                int y = cur.second;
                size++;

                for (int k = 0; k < 4; k++) {
                    int nx = x + dx[k];
                    int ny = y + dy[k];

                    if (nx >= 0 && nx < n && ny >= 0 && ny < m && !visited[nx][ny]) {
                        int nextColor = (state >> (nx * m + ny)) & 1;
                        if (nextColor == color) {
                            visited[nx][ny] = true;
                            q.push({nx, ny});
                        }
                    }
                }
            }

            // 如果存在偶数大小连通块，则不合法
            if (size % 2 == 0) {
                return false;
            }
        }
    }

    return true;
}


// 统计所有合法布局数量
int solve(int n, int m) {
    int total = n * m;
    int ans = 0;

    // 枚举所有状态
    for (int state = 0; state < (1 << total); state++) {
        if (check(state, n, m)) {
            ans++;
        }
    }

    return ans;
}


int main() {
    int n, m;
    cin >> n >> m;
    cout << solve(n, m) << endl;
    return 0;
}
